import ctypes
from cryptography.hazmat.primitives.ciphers.aead import ChaCha20Poly1305

_lib = None
try:
    _lib = ctypes.CDLL("/usr/local/lib/libcrypto.dylib")
    _lib.EVP_CIPHER_CTX_new.restype = ctypes.c_void_p
    _lib.EVP_CIPHER_CTX_free.argtypes = [ctypes.c_void_p]
    _lib.EVP_CIPHER_fetch.restype = ctypes.c_void_p
    _lib.EVP_CIPHER_fetch.argtypes = [ctypes.c_void_p, ctypes.c_char_p, ctypes.c_char_p]
    _lib.EVP_EncryptInit_ex.argtypes = [ctypes.c_void_p, ctypes.c_void_p, ctypes.c_void_p, ctypes.c_char_p, ctypes.c_char_p]
    _lib.EVP_EncryptUpdate.argtypes = [ctypes.c_void_p, ctypes.c_void_p, ctypes.POINTER(ctypes.c_int), ctypes.c_char_p, ctypes.c_int]
    _lib.EVP_EncryptFinal_ex.argtypes = [ctypes.c_void_p, ctypes.c_void_p, ctypes.POINTER(ctypes.c_int)]
    _lib.EVP_CIPHER_CTX_ctrl.argtypes = [ctypes.c_void_p, ctypes.c_int, ctypes.c_int, ctypes.c_void_p]
    _CIPHER = _lib.EVP_CIPHER_fetch(None, b"ChaCha20-Poly1305", None)
    if not _CIPHER:
        _lib = None
except Exception:
    _lib = None

_PyBytes_FromStringAndSize = ctypes.pythonapi.PyBytes_FromStringAndSize
_PyBytes_FromStringAndSize.restype = ctypes.py_object
_PyBytes_FromStringAndSize.argtypes = [ctypes.c_void_p, ctypes.c_ssize_t]
_PyBytes_AsString = ctypes.pythonapi.PyBytes_AsString
_PyBytes_AsString.restype = ctypes.c_void_p
_PyBytes_AsString.argtypes = [ctypes.py_object]


def _fallback(key, nonce, pt, aad):
    ct = ChaCha20Poly1305(key).encrypt(nonce, pt, aad)
    return {"ciphertext": ct[:-16], "tag": ct[-16:]}


class Solver:
    def solve(self, problem, **kwargs):
        key = problem["key"]; nonce = problem["nonce"]
        pt = problem["plaintext"]; aad = problem["associated_data"]
        if len(key) != 32:
            raise ValueError("Invalid key size")
        if _lib is None or len(nonce) != 12 or len(pt) >= 2**31 or not isinstance(pt, bytes):
            return _fallback(key, nonce, pt, aad)
        L = _lib
        ctx = L.EVP_CIPHER_CTX_new()
        try:
            outl = ctypes.c_int(0)
            if L.EVP_EncryptInit_ex(ctx, _CIPHER, None, key, nonce) != 1:
                return _fallback(key, nonce, pt, aad)
            if aad:
                if L.EVP_EncryptUpdate(ctx, None, ctypes.byref(outl), aad, len(aad)) != 1:
                    return _fallback(key, nonce, pt, aad)
            out = _PyBytes_FromStringAndSize(None, len(pt))
            ptr = _PyBytes_AsString(out)
            if pt:
                if L.EVP_EncryptUpdate(ctx, ptr, ctypes.byref(outl), pt, len(pt)) != 1 or outl.value != len(pt):
                    return _fallback(key, nonce, pt, aad)
            tmp = ctypes.create_string_buffer(32)
            if L.EVP_EncryptFinal_ex(ctx, tmp, ctypes.byref(outl)) != 1:
                return _fallback(key, nonce, pt, aad)
            tag = ctypes.create_string_buffer(16)
            if L.EVP_CIPHER_CTX_ctrl(ctx, 0x10, 16, tag) != 1:  # EVP_CTRL_AEAD_GET_TAG
                return _fallback(key, nonce, pt, aad)
            return {"ciphertext": out, "tag": tag.raw}
        finally:
            L.EVP_CIPHER_CTX_free(ctx)
EOF
python3 benchmark.py"}

