#include <stdint.h>
#include <string.h>
#include <pthread.h>
#include <openssl/evp.h>
typedef unsigned __int128 u128;
typedef uint64_t u64;
#define M44 0xfffffffffffULL
#define M42 0x3ffffffffffULL
typedef struct { u64 v[3]; } fe; /* 44,44,42 limbs */

static inline u64 ld64(const uint8_t*p){u64 x;memcpy(&x,p,8);return x;}
static void fe_from16(fe*f,const uint8_t*p,u64 hibit){u64 t0=ld64(p),t1=ld64(p+8);
 f->v[0]=t0&M44; f->v[1]=((t0>>44)|(t1<<20))&M44; f->v[2]=((t1>>24)&M42)|(hibit<<40);}
/* h = h*r mod p (partially reduced) */
static inline void fe_mul(fe*h,const fe*r){
 u64 r0=r->v[0],r1=r->v[1],r2=r->v[2],s1=r1*20,s2=r2*20;
 u64 h0=h->v[0],h1=h->v[1],h2=h->v[2];
 u128 d0=(u128)h0*r0+(u128)h1*s2+(u128)h2*s1;
 u128 d1=(u128)h0*r1+(u128)h1*r0+(u128)h2*s2;
 u128 d2=(u128)h0*r2+(u128)h1*r1+(u128)h2*r0;
 u64 c=(u64)(d0>>44); h0=(u64)d0&M44; d1+=c;
 c=(u64)(d1>>44); h1=(u64)d1&M44; d2+=c;
 c=(u64)(d2>>42); h2=(u64)d2&M42; h0+=c*5; c=h0>>44; h0&=M44; h1+=c;
 h->v[0]=h0;h->v[1]=h1;h->v[2]=h2;}
static inline void fe_add(fe*h,const fe*a){h->v[0]+=a->v[0];h->v[1]+=a->v[1];h->v[2]+=a->v[2];}
/* Horner over nblocks full 16B blocks with hibit, starting h=given */
static void poly_blocks(fe*h,const fe*r,const uint8_t*m,size_t nb){
 for(size_t i=0;i<nb;i++){fe t;fe_from16(&t,m+16*i,1);fe_add(h,&t);fe_mul(h,r);}}
static void fe_pow(fe*out,const fe*r,u64 e){fe res={{1,0,0}};fe b=*r;
 while(e){if(e&1)fe_mul(&res,&b);fe_mul(&b,&b);e>>=1;} *out=res;}

typedef struct { const uint8_t*key,*nonce,*pt; uint8_t*out; size_t off,len; int last; fe r; fe H; u64 nb; int ok;} job;
#define SUB 16384
static void* worker(void*a){job*j=(job*)a; j->ok=0;
 EVP_CIPHER_CTX*ctx=EVP_CIPHER_CTX_new(); uint8_t iv[16]; uint32_t ctr=(uint32_t)(1+j->off/64);
 memcpy(iv,&ctr,4); memcpy(iv+4,j->nonce,12);
 if(EVP_EncryptInit_ex(ctx,EVP_chacha20(),NULL,j->key,iv)!=1){EVP_CIPHER_CTX_free(ctx);return 0;}
 fe h={{0,0,0}}; u64 nb=0; size_t done=0;
 while(done<j->len){size_t n=j->len-done; if(n>SUB)n=SUB; int ol;
  const uint8_t*src=j->pt+j->off+done; uint8_t*dst=j->out+j->off+done;
  if(EVP_EncryptUpdate(ctx,dst,&ol,src,(int)n)!=1){EVP_CIPHER_CTX_free(ctx);return 0;}
  size_t full=n/16; poly_blocks(&h,&j->r,dst,full); nb+=full;
  if(n%16){uint8_t b[16]={0}; memcpy(b,dst+full*16,n%16); poly_blocks(&h,&j->r,b,1); nb++;}
  done+=n;}
 EVP_CIPHER_CTX_free(ctx); j->H=h; j->nb=nb; j->ok=1; return 0;}

static void fe_final(uint8_t tag[16],fe*h,const uint8_t s[16]){
 u64 h0=h->v[0],h1=h->v[1],h2=h->v[2],c;
 c=h1>>44;h1&=M44;h2+=c;c=h2>>42;h2&=M42;h0+=c*5;c=h0>>44;h0&=M44;h1+=c;c=h1>>44;h1&=M44;h2+=c;c=h2>>42;h2&=M42;h0+=c*5;c=h0>>44;h0&=M44;h1+=c;
 u64 g0=h0+5;c=g0>>44;g0&=M44;u64 g1=h1+c;c=g1>>44;g1&=M44;u64 g2=h2+c-(1ULL<<42);
 c=(g2>>63)-1; g0&=c;g1&=c;g2&=c; c=~c; h0=(h0&c)|g0;h1=(h1&c)|g1;h2=(h2&c)|g2;
 u64 t0=ld64(s),t1=ld64(s+8);
 h0+=t0&M44; c=h0>>44;h0&=M44; h1+=(((t0>>44)|(t1<<20))&M44)+c; c=h1>>44;h1&=M44; h2+=(t1>>24)+c; h2&=M42;
 u64 o0=h0|(h1<<44), o1=(h1>>20)|(h2<<24); memcpy(tag,&o0,8);memcpy(tag+8,&o1,8);}

int ccp_encrypt(const uint8_t*key,const uint8_t*nonce,const uint8_t*aad,size_t aadlen,const uint8_t*pt,size_t len,uint8_t*out,uint8_t*tag,int nthreads){
 uint8_t blk[64]={0},iv[16]={0}; memcpy(iv+4,nonce,12);
 EVP_CIPHER_CTX*ctx=EVP_CIPHER_CTX_new(); int ol;
 if(EVP_EncryptInit_ex(ctx,EVP_chacha20(),NULL,key,iv)!=1||EVP_EncryptUpdate(ctx,blk,&ol,blk,64)!=1){EVP_CIPHER_CTX_free(ctx);return -1;}
 EVP_CIPHER_CTX_free(ctx);
 uint8_t rb[16]; memcpy(rb,blk,16);
 rb[3]&=15;rb[7]&=15;rb[11]&=15;rb[15]&=15;rb[4]&=252;rb[8]&=252;rb[12]&=252;
 fe r; fe_from16(&r,rb,0);
 fe h={{0,0,0}};
 size_t af=aadlen/16; poly_blocks(&h,&r,aad,af);
 if(aadlen%16){uint8_t b[16]={0};memcpy(b,aad+af*16,aadlen%16);poly_blocks(&h,&r,b,1);}
 if(len){
  if(nthreads<1)nthreads=1; if(nthreads>64)nthreads=64;
  size_t nblk64=(len+63)/64; if((size_t)nthreads>nblk64)nthreads=(int)nblk64;
  job jobs[64]; pthread_t th[64];
  size_t per=nblk64/nthreads, rem=nblk64%nthreads, o=0;
  for(int i=0;i<nthreads;i++){size_t nbk=per+((size_t)i<rem); size_t l=nbk*64; if(o+l>len)l=len-o;
   jobs[i]=(job){key,nonce,pt,out,o,l,i==nthreads-1,r,{{0,0,0}},0,0}; o+=l;}
  for(int i=1;i<nthreads;i++)pthread_create(&th[i],NULL,worker,&jobs[i]);
  worker(&jobs[0]);
  for(int i=1;i<nthreads;i++)pthread_join(th[i],NULL);
  u64 total=0; for(int i=0;i<nthreads;i++){if(!jobs[i].ok)return -2; total+=jobs[i].nb;}
  fe acc; fe_pow(&acc,&r,total); fe_mul(&h,&acc); /* h0*r^total; fe_mul on h with acc */
  u64 after=total;
  for(int i=0;i<nthreads;i++){after-=jobs[i].nb; fe p; fe_pow(&p,&r,after); fe t=jobs[i].H; fe_mul(&t,&p); fe_add(&h,&t);
   /* normalize carries */ u64 c=h.v[0]>>44;h.v[0]&=M44;h.v[1]+=c;c=h.v[1]>>44;h.v[1]&=M44;h.v[2]+=c;c=h.v[2]>>42;h.v[2]&=M42;h.v[0]+=c*5;}
 }
 uint8_t lb[16]; u64 a=aadlen,c=len; memcpy(lb,&a,8);memcpy(lb+8,&c,8);
 poly_blocks(&h,&r,lb,1);
 fe_final(tag,&h,blk+16);
 return 0;}
